def transform(grid):
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(3 * h):
        block_r, offset_r = divmod(r, h)
        src_r = offset_r if block_r % 2 else h - 1 - offset_r
        row = []
        for c in range(2 * w):
            if c < w:
                src_c = w - 1 - c
            else:
                src_c = c - w
            row.append(grid[src_r][src_c])
        out.append(row)
    return out
